const KAYLA_TUTORIAL_SPRITES={"smile":"data:image/webp;base64,","explain":"data:image/webp;base64,"};
// Chapter 1, part 1: guidance over the real duel, never a separate simulation.
const KaylaGuide=(()=>{
 let step=0,finished=false,frame=0,previousFocus=null;
 const messages=[null,
  "Bienvenue dans ton premier duel officiel de la Triade d’Hackénia ! Je vais t’expliquer pas à pas comment ça se passe, tu vas devenir un(e) pro en deux minutes !",
  "La partie commence et, comme le jeu te l’indique ici, c’est à toi de jouer ! Alors choisis une des cinq cartes de ta main.",
  "Place ta carte sur l’une des 9 cases du plateau.",
  "Génial ! Tu as placé ta première carte ! Mais ton tour n’est pas terminé !",
  "Comme tu le vois ici, tu peux, si tu le souhaites, piocher une carte Souvenir ! Tu peux aussi ne pas piocher et passer au tour de l’adversaire…",
  "Mais attention ! Tu ne peux piocher que deux fois dans cette pioche. Ces petits cristaux t’indiqueront combien de fois tu as déjà pioché !",
  "Certaines cartes de la pioche auront des effets spéciaux en partie, je te laisse découvrir cela par toi-même ! Hihi !",
  "Maintenant tu sais tout ! Choisis si tu pioches un Souvenir ou si tu passes pour continuer la partie. Bonne chance !"
 ];
 const active=()=>step>0&&(currentMode==='story'||currentMode==='tutorial')&&matchInProgress&&!document.querySelector('#gameApp').classList.contains('hidden');
 const targets=()=>step===2?['#turn','#playerHand']:step===3?['#board']:step===4||step===5?['.memory-zone']:step===6?['#pMemoryOrbs']:[];
 function ensure(){
  if(document.querySelector('#kaylaGuide'))return;
  const style=document.createElement('style');style.textContent=`
   #kaylaGuide{position:fixed;inset:0;z-index:100005;pointer-events:none}
   #kaylaGuide.hidden{display:none!important}
   #kaylaGuideMask,#kaylaGuideArrows{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
   #kaylaGuideCard{position:absolute;display:grid;grid-template-columns:110px minmax(0,1fr);gap:12px;align-items:center;width:min(430px,calc(100vw - 24px));box-sizing:border-box;padding:16px;border:1px solid #d9bd7d;border-radius:20px;background:linear-gradient(145deg,#204941,#102e31);color:#f9ebc3;box-shadow:0 8px 28px #0009;pointer-events:auto;max-height:calc(100dvh - 24px);overflow:auto}
   #kaylaGuidePortrait{width:100%;height:180px;object-fit:contain;filter:drop-shadow(0 3px 4px #001e2280)}
   #kaylaGuideCard h2{font:bold 21px Georgia,serif;margin:0 0 6px;color:#f3d68d;text-align:left}
   #kaylaGuideProgress{display:block;font:600 11px system-ui,sans-serif;color:#c5d5bb;margin-bottom:6px}
   #kaylaGuideText{margin:0;font:15px/1.45 system-ui,sans-serif}
   #kaylaGuideNext{margin-top:12px;min-height:44px;padding:8px 16px;border:1px solid #d6b36e;border-radius:999px;background:linear-gradient(#f5e3ac,#d9ba73);color:#322815;font:700 13px system-ui,sans-serif;cursor:pointer}
   #kaylaGuideNext:focus-visible{outline:2px solid #fff3b5;outline-offset:3px}
   #kaylaGuideInstruction{display:block;margin-top:10px;font:600 12px/1.4 system-ui,sans-serif;color:#f3d68d}
   @media(max-width:700px){#kaylaGuideCard{grid-template-columns:65px minmax(0,1fr);gap:9px;padding:11px;border-radius:14px}#kaylaGuidePortrait{height:112px}#kaylaGuideCard h2{font-size:17px}#kaylaGuideText{font-size:13px;line-height:1.4}#kaylaGuideNext{margin-top:8px}}
   @media(max-height:500px){#kaylaGuidePortrait{height:95px}#kaylaGuideCard{padding:10px;grid-template-columns:65px minmax(0,1fr)}#kaylaGuideText{font-size:12px}}
  `;document.head.append(style);
  const root=document.createElement('section');root.id='kaylaGuide';root.className='hidden';root.setAttribute('aria-label','Tutoriel de Kayla');
  root.innerHTML=`<svg id="kaylaGuideMask" aria-hidden="true"><defs><mask id="kaylaSpotlight" maskUnits="userSpaceOnUse"><rect id="kaylaMaskBase" fill="white"/><g id="kaylaMaskHoles"></g></mask></defs><rect id="kaylaShade" fill="black" fill-opacity=".66" mask="url(#kaylaSpotlight)"/><g id="kaylaHighlights"></g></svg><svg id="kaylaGuideArrows" aria-hidden="true"></svg><article id="kaylaGuideCard" tabindex="-1"><img id="kaylaGuidePortrait" alt="Kayla vous explique le duel"><div><span id="kaylaGuideProgress"></span><h2>Kayla</h2><p id="kaylaGuideText" aria-live="polite"></p><span id="kaylaGuideInstruction"></span><button id="kaylaGuideNext" type="button">Continuer →</button></div></article>`;
  document.body.append(root);document.querySelector('#kaylaGuideNext').onclick=advance;
 }
 function checkpoint(){if(currentMode==='story'){saveStoryMatch();if(saveSlotActive)syncProgressSave()}}
 function show(n){
  ensure();step=n;document.querySelector('#kaylaGuide').classList.remove('hidden');
  document.querySelector('#kaylaGuideText').textContent=messages[n];
  document.querySelector('#kaylaGuideProgress').textContent=`Premier duel · ${n} / 8`;
  const portrait=document.querySelector('#kaylaGuidePortrait');portrait.src=KAYLA_TUTORIAL_SPRITES[n===2||n===6?'explain':'smile'];
  const next=document.querySelector('#kaylaGuideNext'),waiting=n===2||n===3;
  next.hidden=waiting;next.textContent=n===8?'À moi de choisir →':'Continuer →';
  document.querySelector('#kaylaGuideInstruction').textContent=n===2?'Touche une carte de ta main pour continuer.':n===3?'Touche une case libre pour y poser ta carte.':'';
  // Reading steps have a focus loop; the two action steps focus real game controls.
  (waiting?document.querySelector(n===2?'#playerHand .card':'#board .cell:not(:has(.card))'):next)?.focus({preventScroll:true});
  layout();checkpoint();
 }
 function bounds(selector){const el=document.querySelector(selector);if(!el)return null;const r=el.getBoundingClientRect();if(r.width<=0||r.height<=0)return null;return {x:Math.max(4,r.left-5),y:Math.max(4,r.top-5),w:Math.min(innerWidth-8,r.width+10),h:Math.min(innerHeight-8,r.height+10)}}
 function layout(){
  if(!active())return;
  const w=innerWidth,h=innerHeight,rects=targets().map(bounds).filter(Boolean);
  for(const id of ['kaylaMaskBase','kaylaShade']){const el=document.getElementById(id);el.setAttribute('width',w);el.setAttribute('height',h)}
  document.getElementById('kaylaShade').setAttribute('fill-opacity',step===8?'0':'.66');
  document.getElementById('kaylaMaskHoles').innerHTML=rects.map(r=>`<rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" rx="10" fill="black"/>`).join('');
  document.getElementById('kaylaHighlights').innerHTML=rects.map(r=>`<rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" rx="10" fill="none" stroke="#f4d78b" stroke-width="2"/>`).join('');
  const pane=document.getElementById('kaylaGuideCard'),pw=pane.offsetWidth,ph=pane.offsetHeight;
  const candidates=[{x:12,y:h-ph-12},{x:w-pw-12,y:h-ph-12},{x:12,y:64},{x:w-pw-12,y:64},{x:(w-pw)/2,y:64},{x:(w-pw)/2,y:h-ph-12}];
  const overlap=p=>rects.reduce((s,r)=>s+Math.max(0,Math.min(p.x+pw,r.x+r.w)-Math.max(p.x,r.x))*Math.max(0,Math.min(p.y+ph,r.y+r.h)-Math.max(p.y,r.y)),0);
  candidates.forEach(p=>{p.y=Math.max(12,Math.min(h-ph-12,p.y));p.x=Math.max(12,p.x)});
  candidates.sort((a,b)=>overlap(a)-overlap(b));const p=candidates[0];pane.style.left=p.x+'px';pane.style.top=p.y+'px';
  const arrows=[];
  // A filled ruby arrow with a fine warm outline, always outside its target.
  const arrow=(x,y,angle,length=46)=>{
   if(length<22)return;
   arrows.push(`<g transform="translate(${x} ${y}) rotate(${angle})" filter="url(#kaylaArrowShadow)"><path d="M0 0 L-17 -11 L-17 -4 Q-${length*.66} -6 -${length} -3 L-${length} 3 Q-${length*.66} 6 -17 4 L-17 11 Z" fill="url(#kaylaArrowRuby)" stroke="#ffd3a1" stroke-width="1.1" stroke-linejoin="round"/></g>`);
  };
  const targetArrow=(r,preferred='top')=>{
   const choices=[
    {side:'left',x:r.x-8,y:r.y+r.h/2,angle:0,room:r.x-20},
    {side:'right',x:r.x+r.w+8,y:r.y+r.h/2,angle:180,room:w-r.x-r.w-20},
    {side:'top',x:r.x+r.w/2,y:r.y-8,angle:90,room:r.y-20},
    {side:'bottom',x:r.x+r.w/2,y:r.y+r.h+8,angle:-90,room:h-r.y-r.h-20}
   ];
   const overlapsPane=c=>{const length=Math.min(46,c.room),rad=c.angle*Math.PI/180;
    const x=c.x-Math.cos(rad)*length/2,y=c.y-Math.sin(rad)*length/2;
    return x>p.x-12&&x<p.x+pw+12&&y>p.y-12&&y<p.y+ph+12};
   const choice=choices.filter(c=>c.room>=22&&!overlapsPane(c)).sort((a,b)=>(b.side===preferred)-(a.side===preferred)||b.room-a.room)[0];
   if(choice)arrow(choice.x,choice.y,choice.angle,Math.min(46,choice.room));
  };
  if(step===3){
   const grid=document.querySelector('#board').getBoundingClientRect();
   const left=grid.left-18,right=grid.right+18;
   const leftRoom=left-12,rightRoom=w-right-12;
   // Desktop: three arrows on each exterior side, aligned with the rows.
   if(leftRoom>=30||rightRoom>=30){
    for(let row=0;row<3;row++){const y=grid.top+grid.height*(row+.5)/3;
     if(leftRoom>=30)arrow(left,y,0,Math.min(46,leftRoom));
     if(rightRoom>=30)arrow(right,y,180,Math.min(46,rightRoom));
    }
   }else{
    // Narrow portrait screens: use the exterior top/bottom edges instead.
    for(let col=0;col<3;col++){const x=grid.left+grid.width*(col+.5)/3;
     arrow(x,grid.top-12,90,Math.min(38,grid.top-24));
     arrow(x,grid.bottom+12,-90,Math.min(38,h-grid.bottom-24));
    }
   }
  }else if(step===5){
   ['#memoryPile','#memoryPassBtn'].forEach(s=>{const r=bounds(s);if(r)targetArrow(r,'bottom')});
  }else if(step===2){
   const hand=bounds('#playerHand'),indicator=bounds('#turn');
   if(hand)targetArrow(hand,'top');if(indicator)targetArrow(indicator,'right');
  }else rects.forEach(r=>targetArrow(r,step===6?'bottom':'top'));
  document.getElementById('kaylaGuideArrows').innerHTML='<defs><linearGradient id="kaylaArrowRuby" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ff7777"/><stop offset=".45" stop-color="#ef343f"/><stop offset="1" stop-color="#a8102c"/></linearGradient><filter id="kaylaArrowShadow" x="-60%" y="-100%" width="220%" height="300%"><feDropShadow dx="0" dy="2" stdDeviation="2" flood-color="#170407" flood-opacity=".8"/></filter></defs>'+arrows.join('');
 }
 function schedule(){if(!frame)frame=requestAnimationFrame(()=>{frame=0;layout()})}
 function advance(){if(!active())return;if(step===1)show(2);else if(step>=4&&step<8)show(step+1);else if(step===8){finished=true;hide();checkpoint();document.querySelector('#memoryPile')?.focus({preventScroll:true})}}
 function hide(){step=0;document.querySelector('#kaylaGuide')?.classList.add('hidden')}
 function begin(){hide();finished=false;previousFocus=document.activeElement;show(1)}
 function selectedCard(){if(active()&&step===2)show(3)}
 function postPlay(owner){if((currentMode==='story'||currentMode==='tutorial')&&owner==='p'&&!finished&&step===3){show(4);return true}return false}
 function snapshot(){return (currentMode==='story'||currentMode==='tutorial')?{step,finished}:null}
 function restore(saved){
  hide();finished=!!saved?.finished;
  if(currentMode!=='story'||finished)return false;
  const count=board.filter(Boolean).length;
  if(count===0){show(saved?.step===1?1:2);return true}
  if(count===1&&turn==='p'&&canDrawMemory('p')){
   offerPostPlayMemory('p');show(Math.max(4,Math.min(8,saved?.step||4)));return true;
  }
  finished=true;return false;
 }
 function allowed(el){if(!active())return true;if(el.closest('#kaylaGuide'))return true;if(step===2)return !!el.closest('#playerHand');if(step===3)return !!el.closest('#playerHand,#board');return false}
 for(const type of ['pointerdown','click','keydown'])document.addEventListener(type,event=>{
  if(!active())return;
  if(type==='keydown'&&event.key==='Tab'&&step!==2&&step!==3){event.preventDefault();document.querySelector('#kaylaGuideNext').focus();return}
  if(!allowed(event.target)){event.preventDefault();event.stopImmediatePropagation()}
 },true);
 window.addEventListener('resize',schedule);document.addEventListener('scroll',schedule,true);window.visualViewport?.addEventListener('resize',schedule);
 return {begin,hide,selectedCard,postPlay,snapshot,restore,get active(){return active()}};
})();
